export const TRICK_KEY = "amphipod";
export const TRICKS = ["sideswim", "gnathopod", "detritusclutch", "pairguard", "urosome", "pleopod", "gammarus"] as const;
export const HAPPY = ["densscud", "inkscud", "densgnath"] as const;
export type AmphipodTrickKind = (typeof TRICKS)[number];
export type AmphipodHappyKind = (typeof HAPPY)[number];
export type TrickAnim = "idle" | "walk" | "sit" | "sleep" | "talk" | "play";
export type TrickPhase = "go" | "hold" | "release" | "done";
export type HappyPhase = "go" | "done";

export type TrickFlags = {
  asleep?: boolean;
  hidden?: boolean;
  leaving?: boolean;
  cmd?: string;
  windowPlay?: boolean;
  card?: boolean;
};

export type AmphipodTrick = {
  kind: AmphipodTrickKind;
  phase: TrickPhase;
  t: number;
  x: number;
  lift: number;
  rot: number;
  anim: TrickAnim;
  facing: 1 | -1;
  fromX: number;
  abort?: boolean;
};

export type AmphipodHappy = {
  kind: AmphipodHappyKind;
  happy: true;
  phase: HappyPhase;
  t: number;
  x: number;
  lift: number;
  rot: number;
  anim: TrickAnim;
  facing: 1 | -1;
  fromX: number;
  abort?: boolean;
};

export const HAPPY_DUR = { densscud: 1.70, inkscud: 1.84, densgnath: 1.76 } as const;
export const GAMMARUS_HOLD = 11.2;
export const RELEASE_S = 1.18;
export const DUR = {
  gammarus: GAMMARUS_HOLD + RELEASE_S,
  sideswim: 2.48,
  gnathopod: 2.42,
  detritusclutch: 2.40,
  pairguard: 2.44,
  urosome: 2.38,
  pleopod: 2.56,
} as const;

export function canStart(state: TrickFlags | undefined) {
  if (!state) return false;
  if (state.asleep || state.hidden || state.leaving || state.windowPlay || state.card) return false;
  const cmd = String(state.cmd || "");
  if (cmd === "sleep" || cmd === "leave" || cmd === "hide" || cmd === "rest") return false;
  if (cmd === "seek" || cmd === "eat" || cmd === "play" || cmd === "talk" || cmd === "enter") return false;
  return true;
}

export function shouldAbort(state: TrickFlags | undefined) {
  if (!state) return true;
  if (state.asleep || state.hidden || state.leaving || state.windowPlay || state.card) return true;
  const cmd = String(state.cmd || "");
  return (
    cmd === "sleep" ||
    cmd === "leave" ||
    cmd === "hide" ||
    cmd === "rest" ||
    cmd === "seek" ||
    cmd === "eat" ||
    cmd === "play" ||
    cmd === "talk" ||
    cmd === "enter"
  );
}

export function nextTrickWait(justFinished: boolean, rand?: number, kind?: AmphipodTrickKind | string) {
  const roll = rand == null ? Math.random() : rand;
  if (kind === "gammarus") return 40 + roll * 26;
  if (kind === "urosome" || kind === "sideswim" || kind === "pairguard") return 12.8 + roll * 9.4;
  if (kind === "detritusclutch" || kind === "gnathopod" || kind === "pleopod") return 11.6 + roll * 8.5;
  return justFinished ? 8.5 + roll * 8.4 : 4.4 + roll * 7.4;
}

